//
//  StaticEntropyCodes.swift
//  JXLEncoder
//
//  The precomputed prefix codes and context maps from libjxl-tiny's
//  encoder/static_entropy_codes.h, as resolved with OPTIMIZE_CODE = 0.
//
//  Generated by Reference/tools/gencodes.cc, which prints the tables the
//  compiler actually sees; the header nests them inside preprocessor branches
//  that are easy to misread.
//
//  Using these costs ~19-24% in size versus per-image optimized Huffman trees,
//  but the decoded pixels are byte-identical either way, so this is purely an
//  entropy-layer tradeoff and a safe starting point.
//

/// Canonical prefix code over the 64-symbol token alphabet. A depth of zero
/// means the symbol is unused.
public struct PrefixCode: Sendable {
	public let depths: [UInt8]
	public let bits: [UInt16]

	public init(depths: [UInt8], bits: [UInt16]) {
		self.depths = depths
		self.bits = bits
	}
}

